import "server-only";
import { mkdir, readFile, writeFile, unlink } from "node:fs/promises";
import { join, resolve, sep } from "node:path";
import { DeleteObjectsCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { env } from "../env";

/**
 * Object keys are always generated by the server (UUIDs), never taken from
 * the client, and validated against this pattern before any filesystem or
 * S3 access — this rules out path traversal.
 */
export const OBJECT_KEY = /^products\/[a-f0-9-]{36}-(?:400|800|1200)\.webp$/;

export interface Storage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  remove(keys: string[]): Promise<void>;
}

const LOCAL_ROOT = resolve(process.cwd(), ".data", "uploads");

export function localPath(key: string): string {
  if (!OBJECT_KEY.test(key)) throw new Error("invalid key");
  const p = resolve(LOCAL_ROOT, key);
  if (!p.startsWith(LOCAL_ROOT + sep)) throw new Error("invalid key");
  return p;
}

const localStorage: Storage = {
  async put(key, body) {
    const p = localPath(key);
    await mkdir(join(LOCAL_ROOT, "products"), { recursive: true });
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- path comes from localPath(), which validates the key
    await writeFile(p, body);
  },
  async remove(keys) {
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- path comes from localPath(), which validates the key
    await Promise.all(keys.map((k) => unlink(localPath(k)).catch(() => undefined)));
  },
};

export async function readLocalObject(key: string): Promise<Buffer | null> {
  try {
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- path comes from localPath(), which validates the key
    return await readFile(localPath(key));
  } catch {
    return null;
  }
}

let s3: S3Client | null = null;
const s3Storage: Storage = {
  async put(key, body, contentType) {
    if (!OBJECT_KEY.test(key)) throw new Error("invalid key");
    s3 ??= new S3Client({ region: env().AWS_REGION });
    await s3.send(
      new PutObjectCommand({
        Bucket: env().S3_BUCKET,
        Key: key,
        Body: body,
        ContentType: contentType,
        CacheControl: "public, max-age=31536000, immutable",
      }),
    );
  },
  async remove(keys) {
    const valid = keys.filter((k) => OBJECT_KEY.test(k));
    if (!valid.length) return;
    s3 ??= new S3Client({ region: env().AWS_REGION });
    await s3.send(
      new DeleteObjectsCommand({ Bucket: env().S3_BUCKET, Delete: { Objects: valid.map((Key) => ({ Key })) } }),
    );
  },
};

export function storage(): Storage {
  return env().STORAGE_DRIVER === "s3" ? s3Storage : localStorage;
}
